326 |     function _transfer(
327 |         TokenType tokenType,
328 |         address token,
329 |         address payable recipient,
330 |         uint256 amount
331 |     ) private {
332 |         bytes32 balanceId = _getBalanceId(tokenType, token);
333 |         // Reduce stored token balance.
334 |         uint256 storedBalance = _storedBalances[balanceId] - amount;
335 |         // Temporarily set to max as a reentrancy guard. An interesing attack
336 |         // could occur if we didn't do this where an attacker could `claim()` and
337 |         // reenter upon transfer (e.g. in the `tokensToSend` hook of an ERC777) to
338 |         // `createERC20Distribution()`. Since the `balanceOf(address(this))`
339 |         // would not of been updated yet, the supply would be miscalculated and
340 |         // the attacker would create a distribution that essentially steals from
341 |         // the last distribution they were claiming from. Here, we prevent that
342 |         // by causing an arithmetic underflow with the supply calculation if
343 |         // this were to be attempted.
344 |         _storedBalances[balanceId] = type(uint256).max;
345 |         if (tokenType == TokenType.Native) {
346 |             recipient.transferEth(amount);
347 |         } else {
348 |             assert(tokenType == TokenType.Erc20);
349 |             IERC20(token).compatTransfer(recipient, amount);
350 |         }
351 |         _storedBalances[balanceId] = storedBalance;
352 |     }
