354 |     function _getDistributionHash(
355 |         DistributionInfo memory info
356 |     ) internal pure returns (bytes32 hash) {
357 |         assembly {
358 |             hash := keccak256(info, 0xe0)
359 |         }
360 |     }
361 | 
362 |     function _getBalanceId(
363 |         TokenType tokenType,
364 |         address token
365 |     ) private pure returns (bytes32 balanceId) {
366 |         if (tokenType == TokenType.Native) {
367 |             return bytes32(uint256(uint160(NATIVE_TOKEN_ADDRESS)));
368 |         }
369 |         assert(tokenType == TokenType.Erc20);
370 |         return bytes32(uint256(uint160(token)));
371 |     }
